def merge_intervals(items):
    if not items:
        return []

    # Sort intervals by start time
    items.sort()

    merged = []
    for item in items:
        if not merged or merged[-1][1] < item[0]:
            # No overlap, add the interval as is
            merged.append(item)
        else:
            # Overlap, merge with the last interval
            merged[-1][1] = max(merged[-1][1], item[1])

    return merged
```

